registerPaint('checkerboard', class {
  paint(ctx, size) {
    const tile = 20;
    for (let y = 0; y < size.height; y += tile) {
      for (let x = 0; x < size.width; x += tile) {
        ctx.fillStyle = (Math.floor(x/tile)+Math.floor(y/tile))%2 ? '#eee' : '#fff';
        ctx.fillRect(x, y, tile, tile);
      }
    }
  }
});

