/* Component exposes parts: */
/* <my-button><button part="button">Click</button></my-button> */

my-button::part(button) {
  background: var(--brand);
  color: white;
  border-radius: 4px;
}

@container style(--variant: primary) {
  .btn { background: blue; color: white; }
}

@keyframes progress {
  to { transform: scaleX(1); }
}
.progress-bar {
  animation: progress linear;
  animation-timeline: scroll(root block);
  transform-origin: left;
  transform: scaleX(0);
}

.card {
  view-transition-name: card-1;
}

::view-transition-old(card-1) {
  animation: slide-out 0.3s ease;
}
::view-transition-new(card-1) {
  animation: slide-in 0.3s ease;
}

:root { interpolate-size: allow-keywords; }

.expandable {
  height: 0;
  overflow: hidden;
  transition: height 0.3s;
}
.expandable.open { height: auto; }

.card:hover {
  translate: 0 -4px;
  scale: 1.02;
  rotate: 2deg;
}

.article {
  h1 { font-size: 2rem; }
  p { line-height: 1.6; }
  & > footer {
    font-size: 0.875rem;
    color: #666;
  }
}

dialog {
  transition: opacity 0.3s, transform 0.3s, display 0.3s allow-discrete;
  opacity: 1;
  transform: translateY(0);
}

@starting-style {
  dialog[open] {
    opacity: 0;
    transform: translateY(-20px);
  }
}

.popover {
  display: none;
  transition: opacity 0.3s, display 0.3s allow-discrete;
  opacity: 0;
}
.popover.visible {
  display: block;
  opacity: 1;
}
@starting-style { .popover.visible { opacity: 0; } }

:root { color-scheme: light dark; }

body {
  background: light-dark(white, #1a1a1a);
  color: light-dark(#111, #f0f0f0);
}

:root {
  --brand: oklch(60% 0.2 30);
  --brand-light: oklch(80% 0.15 30);
