}

/* Generate a 10-step palette: */
.swatch-1 { background: oklch(95% 0.05 250); }
.swatch-5 { background: oklch(65% 0.2 250); }
.swatch-9 { background: oklch(25% 0.1 250); }

.safe-area {
  padding-top: env(safe-area-inset-top);
  padding-bottom: env(safe-area-inset-bottom);
  padding-left: env(safe-area-inset-left);
  padding-right: env(safe-area-inset-right);
}

body {
  display: grid;
  grid-template-rows: auto 1fr auto;
  min-height: 100dvh;
}

header { /* auto height */ }
main { /* 1fr — expands to fill */ }
footer { /* auto height */ }

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* Full feature detection example */
@supports (display: grid) and (gap: 1rem) {
  .layout {
    display: grid;
    gap: 1rem;
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 300px), 1fr));
  }
}

@supports not (display: grid) {
  .layout { display: flex; flex-wrap: wrap; }
  .layout > * { margin: 0.5rem; flex: 1 1 300px; }
}
